<?php $title = 'Produkty admin | ShopStack'; require __DIR__ . '/../layouts/header.php'; ?><p class="eyebrow">ADMIN / PRODUKTY</p><h1>Produkty</h1><form class="admin-form" method="post" enctype="multipart/form-data" action="<?= e($config['url']) ?>/admin/products/save"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input name="name" placeholder="Nazwa" required><input name="slug" placeholder="Slug" required><select name="category_id" required><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select><input name="price" type="number" step="0.01" placeholder="Cena" required><input name="stock" type="number" placeholder="Stan" required><textarea name="description" placeholder="Opis" required></textarea><label>Zdjęcie (opcjonalnie)<input name="image_upload" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="button">Dodaj produkt</button></form><div class="table-list"><?php foreach ($products as $product): ?><div class="line-item"><span><strong><?= e($product['name']) ?></strong><small><?= e($product['category_name']) ?></small></span><span><?= money($product['price']) ?></span><span><?= e($product['stock']) ?> szt.</span><span><a href="<?= e($config['url']) ?>/admin/products/edit/<?= e($product['id']) ?>">Edytuj</a> <form class="inline" method="post" action="<?= e($config['url']) ?>/admin/products/delete/<?= e($product['id']) ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><button class="link-button">Usuń</button></form></span></div><?php endforeach; ?></div><?php require __DIR__ . '/../layouts/footer.php'; ?>
